function placeChoices(correct, distractors, correctIndex) {
  const choices = [];
  let distractorIndex = 0;
  for (let index = 0; index < 4; index += 1) choices.push(index === correctIndex ? correct : distractors[distractorIndex++]);
  return choices;
}

function createTest(chapter) {
  const positions = ANSWER_POSITIONS[chapter.number - 1];
  const id = `${BOOK_ID}-chapter-${chapter.number}`;
  return {
    id, bookId: BOOK_ID, bookTitle: BOOK_TITLE, chapterNumber: chapter.number, chapterTitle: chapter.title,
    title: `Chapter ${chapter.number} Check`, status: "published", passingPercent: 80,
    questions: chapter.questions.map((question, index) => ({
      id: `q${index + 1}`, type: "multiple-choice", skill: SKILLS[index], prompt: question[0],
      choices: placeChoices(question[1], question[2], positions[index]), correctIndex: positions[index], explanation: question[3]
    })),
    summaryRequired: true, summarySentenceCount: 5, summaryPrompt: SUMMARY_PROMPT, summaryGuide: chapter.guide,
    generation: { method: "source-grounded-curated-v1", sourcePages: chapter.pages }
  };
}

export const PERCY5_TESTS = Object.fromEntries(chapters.map(chapter => {
  const test = createTest(chapter);
  return [test.id, test];
}));
